<script setup lang="ts">import{ref,onMounted,computed}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import*as runs from '../api/runs';import type{Run}from '../types/domain';import{fmt,pct,ratio}from '../utils/format';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RunSelect from '../components/RunSelect.vue';import RateStrips from '../components/RateStrips.vue';import StratumTable from '../components/StratumTable.vue';import ExactDistribution from '../components/ExactDistribution.vue';const route=useRoute(),selected=ref(0),current=ref<Run|null>(null),r=computed(()=>current.value?.status==='completed'?current.value.result:null),{error,execute}=useTask();let sequence=0;async function switchRun(id:number){selected.value=id;current.value=null;const seq=++sequence;const data=await runs.detail(id);if(seq===sequence&&selected.value===id)current.value=data}function choose(id:number){execute(()=>switchRun(id))}onMounted(()=>execute(async()=>{await load();const id=Number(route.query.run)||lab.runs.find(x=>x.status==='completed')?.id||lab.runs[0]?.id;if(id)await switchRun(id)}));usePolling(()=>{if(current.value&&['queued','running'].includes(current.value.status))execute(async()=>{const id=selected.value;const data=await runs.detail(id);if(selected.value===id)current.value=data;await load()})});</script><template><PageHeading index="04" title="把总体率，拆回每一层。" text="率差、分层OR与条件双侧证据互为参照；没有一种摘要替代层结构。"/><ErrorNotice :message="error" @retry="choose(selected)"/><RunSelect :runs="lab.runs" :model-value="selected" @update:model-value="choose"/><div v-if="current?.status==='failed'" class="empty"><h2>本次计算未完成</h2><p>{{current.error}}</p><RouterLink to="/sources">回到底稿修订 →</RouterLink></div><div v-else-if="!r" class="empty"><h2>正在等待这份冻结研究</h2><p>若队列尚未完成，状态会自动更新；没有结果时请先建立至少2个完整分层。</p><RouterLink to="/configure">打开配置 →</RouterLink></div><template v-if="r&&current"><div class="result-byline"><b>#{{current.id}} / {{current.name}}</b><span>{{r.input_snapshot.study.code}} · {{r.strata.length}}预设层</span></div><div class="result-totals"><div><small>总体成功率 A / B</small><b>{{pct(r.pooled.rate_a)}} <span>/ {{pct(r.pooled.rate_b)}}</span></b></div><div><small>粗 OR</small><b>{{ratio(r.pooled.odds_ratio)}}</b></div><div><small>MH 分层 OR</small><b>{{ratio(r.adjusted_or)}}</b></div><div><small>固定边际精确双侧 p</small><b class="p-value">{{r.exact.p_display}}</b></div></div><div class="results-split"><section><h2>同层独立试片，分别比较。</h2><RateStrips :rows="r.strata"/></section><aside class="evidence-note"><p class="eyebrow">CONDITIONAL ASSOCIATION / NOT CAUSATION</p><h2>{{r.exact.below_alpha?'达到预设探索阈值':'未达到预设探索阈值'}}</h2><p>α = {{r.alpha}}。未拒绝并非证明等效；拒绝也不能单独推断封装造成差异。</p><dl><div><dt>Σa / E[Σa]</dt><dd>{{r.observed_sum_a}} / {{fmt(r.expected_sum_a,6)}}</dd></div><div><dt>Var[Σa]</dt><dd>{{fmt(r.variance_sum_a,6)}}</dd></div><div><dt>CMH / 渐近p</dt><dd>{{fmt(r.cmh,6)}} / {{r.asymptotic_p_display}}</dd></div><div><dt>MH 分子 / 分母</dt><dd>{{fmt(r.mh_numerator,6)}} / {{fmt(r.mh_denominator,6)}}</dd></div></dl><p>连续性修正：否；零格加.5：否。{{r.uninformative_codes.length}}层无条件方差信息，仍保留底稿和标记。</p></aside></div><h2 class="ruled-title">冻结的四格与边际</h2><StratumTable :rows="r.strata"/><section class="distribution-sheet"><div class="section-heading"><h2>固定边际的整个条件分布</h2><span>{{r.exact.support_size}}个支持点 / 质量{{fmt(r.exact.probability_sum,12)}}</span></div><ExactDistribution :exact="r.exact"/><p>精确分布均值{{fmt(r.exact.distribution_mean,8)}}，方差{{fmt(r.exact.distribution_variance,8)}}；来自各层超几何变量卷积。完整p保留为科学计数文本与log值，防止极小数展示为0。</p><details><summary>逐个支持点的概率、log与双侧尾归属</summary><div class="table-wrap exact-mass-table"><table><thead><tr><th>S</th><th>概率</th><th>log概率</th><th>入双侧尾</th></tr></thead><tbody><tr v-for="d in r.exact.distribution" :key="d.s"><td>{{d.s}}</td><td>{{d.probability.toExponential(8)}}</td><td>{{fmt(d.log_probability,8)}}</td><td>{{d.in_tail?'是':'否'}}</td></tr></tbody></table></div></details></section><aside class="interpretation-boundary"><b>研究边界</b><p>{{r.interpretation}}</p><p>{{r.exact.tail_rule}}</p><RouterLink :to="'/notes?run='+current.id">形成独立复验说明 →</RouterLink></aside><details class="fingerprint"><summary>冻结输入指纹与数值口径</summary><code>{{r.fingerprint}}</code><p>{{r.method_version}} / {{r.exact.numeric}}</p><p>条件均值有理数 {{r.exact.mean_numerator}} / {{r.exact.mean_denominator}}；p log {{fmt(r.exact.p_log,10)}}。</p></details></template></template>
